// gh-1027 (CRAP refactor): the per-rule candidate-slice cap, extracted
// from queryPrs so its complexity doesn't compound the query function.
// conflict_rework widens to the shared over-scan budget; every other rule
// keeps the gh-922 fallthrough reserve.
function sliceCap(rule, limit, fallthroughReserve) {
   if (rule && rule.localAction === 'conflict_rework') {
