    test('limit + OVERSCAN for positive limits', function () {
        assert.equal(mod.scanLimit(1), 16, 'limit 1 scans 16 candidates');
        assert.equal(mod.scanLimit(5), 20);
        assert.equal(mod.OVERSCAN, 15);
